def handle_volley(volley):
    claimed = volley.entities[0].strip()
    allowed = {name.lower(): name for name in volley.speaker_names}
    display = allowed.get(claimed.lower())
    if display:
        volley.persist_data['active_speaker'] = display
        volley.set_output(f'Hi {display}! I will remember who is talking.', None)
    else:
        volley.set_output(f'I do not have {claimed} in my speaker list yet. A grown-up can add that name in my OpenMoxie settings.', None)
